import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class DiscountService {
    BigDecimal calculateDiscount(BigDecimal amount, String customerType) {
        if (amount.compareTo(BigDecimal.ZERO) < 0)
            throw new IllegalArgumentException("Amount cannot be negative");
        return "PREMIUM".equals(customerType)
            ? amount.multiply(new BigDecimal("0.15"))
            : amount.multiply(new BigDecimal("0.05"));
    }
}

class DiscountServiceTest {
    private final DiscountService service = new DiscountService();

    @Test
    void calculateDiscount_whenCustomerIsPremium_thenReturns15Percent() {
        assertEquals(new BigDecimal("15.00"),
            service.calculateDiscount(new BigDecimal("100"), "PREMIUM"));
    }

    @Test
    void calculateDiscount_whenAmountIsZero_thenReturnsZero() {
        assertEquals(new BigDecimal("0.00"),
            service.calculateDiscount(BigDecimal.ZERO, "REGULAR"));
    }

    @Test
    void calculateDiscount_whenAmountIsNegative_thenThrowsException() {
        assertThrows(IllegalArgumentException.class,
            () -> service.calculateDiscount(new BigDecimal("-10"), "REGULAR"));
    }
}
